import{_ as t,c as e,o as r,b0 as l}from"./chunks/framework.C5ev1SXp.js";const o="/scm-docs/assets/sar-adc-block.BlsuOPWo.svg",i="/scm-docs/assets/adc-timing.Bx84iIre.svg",d="/scm-docs/assets/adc-quantization.Cmy1LDzD.svg",m=JSON.parse('{"title":"LV001-ADC原理与精度基础","description":null,"frontmatter":{"title":"LV001-ADC原理与精度基础","date":"2026-10-15T07:54:36.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/peripheral/adc/126d629b3a6c1f72a2039f9e","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-10-15T07:54:36.503Z","fulluuid":"2a2039f9e80443f09b675e8bfc744a84","useduuid":"2a2039f9e"}},"headers":[],"relativePath":"sdoc/peripheral/adc/126d629b3a6c1f72a2039f9e.md","filePath":"sdoc/20-基本外设篇/05-ADC/LV001-ADC原理与精度基础.md","lastUpdated":1792035518000}'),n={name:"sdoc/peripheral/adc/126d629b3a6c1f72a2039f9e.md"};function s(h,a,c,u,p,_){return r(),e("div",null,[...a[0]||(a[0]=[l('<h1 id="lv001-adc原理与精度基础" tabindex="-1">LV001-ADC原理与精度基础 <a class="header-anchor" href="#lv001-adc原理与精度基础" aria-label="Permalink to &quot;LV001-ADC原理与精度基础&quot;">​</a></h1><h2 id="一、-adc-在做什么-两次离散化" tabindex="-1">一、 ADC 在做什么：两次离散化 <a class="header-anchor" href="#一、-adc-在做什么-两次离散化" aria-label="Permalink to &quot;一、 ADC 在做什么：两次离散化&quot;">​</a></h2><p>传感器给的是连续信号：温度、压力、电流，时间上连续、幅值上也连续。MCU 只能处理数字量，ADC（Analog-to-Digital Converter，模数转换器）就是两者之间的翻译官，它做两次离散化。</p><h3 id="_1-采样与量化" tabindex="-1">1. 采样与量化 <a class="header-anchor" href="#_1-采样与量化" aria-label="Permalink to &quot;1. 采样与量化&quot;">​</a></h3><ul><li><strong>采样</strong>：时间上离散。每隔固定时间取一个点，连续波形变成一串时间点</li><li><strong>量化</strong>：幅值上离散。把每个点的电压归到最接近的一级台阶上，连续幅值变成整数码</li></ul><p>（1）采样决定&quot;多久看一次&quot;，用采样率描述。</p><p>（2）量化决定&quot;看得多细&quot;，用分辨率描述：N 位 ADC 把量程切成 2^N 级，输出码的取值范围是 0 ～ 2^N - 1。</p><p>两次离散化都丢信息。丢多少、丢在哪、怎么算，就是本篇要讲清楚的东西。</p><h3 id="_2-三个先记住的名词" tabindex="-1">2. 三个先记住的名词 <a class="header-anchor" href="#_2-三个先记住的名词" aria-label="Permalink to &quot;2. 三个先记住的名词&quot;">​</a></h3><ul><li><strong>LSB</strong>（Least Significant Bit）：最低位变化 1 对应的电压变化，也就是台阶高度，1 LSB = V_REF / 2^N</li><li><strong>量程</strong>（Full Scale Range）：ADC 能转换的输入电压范围，单极性 ADC 通常是 0 ～ V_REF</li><li><strong>V_REF</strong>（参考电压）：量程这把尺子。尺子本身不准，量出来的一切都不准</li></ul><h2 id="二、-逐次逼近型-adc-的工作原理" tabindex="-1">二、 逐次逼近型 ADC 的工作原理 <a class="header-anchor" href="#二、-逐次逼近型-adc-的工作原理" aria-label="Permalink to &quot;二、 逐次逼近型 ADC 的工作原理&quot;">​</a></h2><h3 id="_1-为什么是逐次逼近" tabindex="-1">1. 为什么是逐次逼近 <a class="header-anchor" href="#_1-为什么是逐次逼近" aria-label="Permalink to &quot;1. 为什么是逐次逼近&quot;">​</a></h3><p>MCU 片内 ADC 几乎清一色是 SAR 型（Successive Approximation Register，逐次逼近寄存器型）。原因是一笔折中账：闪存型一位一个比较器，快但面积随位数指数上涨；Σ-Δ 型精度高但靠过采样换时间，慢；SAR 型只用一个比较器加一个内部 DAC，N 位做 N 次比较，速度、精度、面积三者都不拔尖但都不差，正好落在 MCU 的需求区间。</p><h3 id="_2-结构-一台猜数字的机器" tabindex="-1">2. 结构：一台猜数字的机器 <a class="header-anchor" href="#_2-结构-一台猜数字的机器" aria-label="Permalink to &quot;2. 结构：一台猜数字的机器&quot;">​</a></h3><p>SAR ADC 的内部就是一场猜数字游戏：心里想一个数（输入电压），猜的人从最高位开始逐位问&quot;这一位置 1 会不会超&quot;。</p><p><img src="'+o+'" alt="SAR ADC 结构框图"></p><ul><li>多路选择器把多个外部通道接到同一条转换通路，所以&quot;几个通道&quot;不等于&quot;几个 ADC&quot;</li><li>采样保持电路在转换开始前把输入电压冻在保持电容上，转换期间输入再变也不影响本次结果</li><li>比较器每个时钟比一次：保持电压与内部 DAC 当前的猜测电压谁大</li><li>SAR 逻辑按 ADCCLK 节拍从最高位起逐位试 1：比较器说没超，这一位留下；说超了，这一位清 0</li><li>N 位比完，数据寄存器里就是转换结果，等 CPU 或 DMA 来取</li></ul><h3 id="_3-时序-先采样-后转换" tabindex="-1">3. 时序：先采样，后转换 <a class="header-anchor" href="#_3-时序-先采样-后转换" aria-label="Permalink to &quot;3. 时序：先采样，后转换&quot;">​</a></h3><p><img src="'+i+'" alt="ADC 采样与转换时序"></p><p>一次完整转换分两段：</p><ul><li><strong>采样阶段</strong>：保持开关闭合，保持电容跟踪输入电压，持续 t_samp，长度可编程</li><li><strong>转换阶段</strong>：开关断开，SAR 用 N 个时钟逐位逼近；12 位 SAR 共需 12.5 个 ADCCLK，即 12 次比较加 0.5 个周期收尾</li></ul><p>于是单次转换时间 t_total = t_samp + t_conv，最高采样率就是它的倒数。这个公式是后面一切采样率计算的根。</p><p>【<strong>注意</strong>】采样时间不是越短越好：保持电容要通过信号源内阻充电，t_samp 内充不到误差小于 1/2 LSB，转换结果从起点就错了。</p><h2 id="三、-量程与码值换算" tabindex="-1">三、 量程与码值换算 <a class="header-anchor" href="#三、-量程与码值换算" aria-label="Permalink to &quot;三、 量程与码值换算&quot;">​</a></h2><h3 id="_1-量程由参考电压决定" tabindex="-1">1. 量程由参考电压决定 <a class="header-anchor" href="#_1-量程由参考电压决定" aria-label="Permalink to &quot;1. 量程由参考电压决定&quot;">​</a></h3><p>单极性 ADC 的量程是 0 ～ V_REF。V_REF 可以是电源本身（如 3.3 V），也可以是外部基准芯片给的更稳的电压（如 2.5 V、4.096 V）。选外部基准的理由只有一个：电源会随负载和温度漂，基准不会，或者漂得小得多。</p><h3 id="_2-两个方向的换算" tabindex="-1">2. 两个方向的换算 <a class="header-anchor" href="#_2-两个方向的换算" aria-label="Permalink to &quot;2. 两个方向的换算&quot;">​</a></h3><ul><li>码转电压：V = code × V_REF / 2^N</li><li>电压转码：code = V × 2^N / V_REF，结果取整</li></ul><p>以 12 位、V_REF = 3.3 V 为例：1 LSB = 3.3 / 4096 ≈ 0.806 mV。读回码 2048 对应 2048 × 0.806 mV ≈ 1.65 V，恰为半量程。</p><h3 id="_3-满量程码是-2-n-1-而不是-2-n" tabindex="-1">3. 满量程码是 2^N - 1 而不是 2^N <a class="header-anchor" href="#_3-满量程码是-2-n-1-而不是-2-n" aria-label="Permalink to &quot;3. 满量程码是 2^N - 1 而不是 2^N&quot;">​</a></h3><p>最后一个码代表的是一段区间而不是一个点：码 4095 覆盖 [V_REF - 1 LSB, V_REF)。输入哪怕真的等于 V_REF，输出也只是 4095。所以&quot;读满量程&quot;永远读不到 4096，这不是 bug。</p><h2 id="四、-精度-分辨率不等于精度" tabindex="-1">四、 精度：分辨率不等于精度 <a class="header-anchor" href="#四、-精度-分辨率不等于精度" aria-label="Permalink to &quot;四、 精度：分辨率不等于精度&quot;">​</a></h2><h3 id="_1-误差从哪来" tabindex="-1">1. 误差从哪来 <a class="header-anchor" href="#_1-误差从哪来" aria-label="Permalink to &quot;1. 误差从哪来&quot;">​</a></h3><p>把误差按来源分三类，性质完全不同：</p><table tabindex="0"><thead><tr><th>类别</th><th>典型项</th><th>能不能消除</th></tr></thead><tbody><tr><td>原理性</td><td>量化误差 ±1/2 LSB</td><td>不能，只能加位数摊薄</td></tr><tr><td>器件性</td><td>偏移误差、增益误差、INL、DNL</td><td>部分可校准</td></tr><tr><td>使用性</td><td>参考漂移、电源噪声、采样不足、布局串扰</td><td>靠设计规避</td></tr></tbody></table><ul><li><strong>偏移误差</strong>：输入为 0 时输出不是 0，整条传递曲线平移，全量程错同一个常数，最好校准</li><li><strong>增益误差</strong>：曲线斜率不对，输入越大错得越多，可用两点校准消掉</li><li><strong>INL / DNL</strong>（积分 / 微分非线性）：台阶相对理想直线的整体弯曲、单级台阶宽度不均，校准不掉，是器件的硬指标</li></ul><h3 id="_2-量化误差-躲不掉的那一份" tabindex="-1">2. 量化误差：躲不掉的那一份 <a class="header-anchor" href="#_2-量化误差-躲不掉的那一份" aria-label="Permalink to &quot;2. 量化误差：躲不掉的那一份&quot;">​</a></h3><p><img src="'+d+'" alt="量化传递函数与量化误差"></p><p>台阶高 1 LSB，落在同一台阶内的所有输入都变成同一个码，所以误差在 ±1/2 LSB 内呈锯齿分布。它是原理性的：与器件好坏无关，与输入信号无关，只与位数有关。位数每加 1，LSB 减半，这份误差跟着减半。</p><h3 id="_3-把总误差算出来" tabindex="-1">3. 把总误差算出来 <a class="header-anchor" href="#_3-把总误差算出来" aria-label="Permalink to &quot;3. 把总误差算出来&quot;">​</a></h3><p>工程上把各项误差按最坏情况相加（保守）或按均方根合成（乐观），datasheet 常直接给一个总未调整误差 TAE。手算一遍 12 位、3.3 V 的典型片子：</p><table tabindex="0"><thead><tr><th>误差项</th><th>典型值</th></tr></thead><tbody><tr><td>量化误差</td><td>±0.5 LSB</td></tr><tr><td>偏移误差</td><td>±2 LSB</td></tr><tr><td>增益误差</td><td>±2 LSB</td></tr><tr><td>INL</td><td>±1.5 LSB</td></tr><tr><td>最坏合计</td><td>±6 LSB</td></tr></tbody></table><p>±6 LSB × 0.806 mV ≈ ±4.8 mV。也就是说这片 12 位 ADC 的真实精度大约是&quot;12 位分辨率、10 位精度&quot;。分辨率告诉你台阶有多细，精度告诉你台阶位置站得准不准，两者不是一回事。</p><h3 id="_4-衡量真实精度的指标-enob" tabindex="-1">4. 衡量真实精度的指标：ENOB <a class="header-anchor" href="#_4-衡量真实精度的指标-enob" aria-label="Permalink to &quot;4. 衡量真实精度的指标：ENOB&quot;">​</a></h3><p>（1）有效位数 ENOB（Effective Number of Bits）把含噪声、含失真的实测表现折回位数：ENOB = (SINAD - 1.76) / 6.02。</p><p>（2）12 位 ADC 的 ENOB 常见 10 ～ 11 位。选型时看 ENOB 比看&quot;12 位&quot;诚实。</p><h2 id="五、-采样率与信号源-三个旋钮" tabindex="-1">五、 采样率与信号源：三个旋钮 <a class="header-anchor" href="#五、-采样率与信号源-三个旋钮" aria-label="Permalink to &quot;五、 采样率与信号源：三个旋钮&quot;">​</a></h2><h3 id="_1-采样定理" tabindex="-1">1. 采样定理 <a class="header-anchor" href="#_1-采样定理" aria-label="Permalink to &quot;1. 采样定理&quot;">​</a></h3><p>（1）奈奎斯特采样定理：要从采样序列无失真地恢复原信号，采样率必须大于信号最高频率的 2 倍。</p><p>（2）工程上不留这么紧：测缓变信号（温度、电池电压）取 5 ～ 10 倍余量；同时用硬件低通把高于半采样率的成分滤掉，否则高频成分会混叠进低频，事后无法区分。</p><h3 id="_2-信号源内阻决定采样时间" tabindex="-1">2. 信号源内阻决定采样时间 <a class="header-anchor" href="#_2-信号源内阻决定采样时间" aria-label="Permalink to &quot;2. 信号源内阻决定采样时间&quot;">​</a></h3><p>保持电容通过信号源内阻充电，是一个 RC 过程。源内阻越大，充到 1/2 LSB 误差内所需时间越长，t_samp 就得配越长。分压电阻取兆欧级省功耗、却把采样时间拖到微秒级，是常见的设计冲突。</p><h3 id="_3-选型时拧的三个旋钮" tabindex="-1">3. 选型时拧的三个旋钮 <a class="header-anchor" href="#_3-选型时拧的三个旋钮" aria-label="Permalink to &quot;3. 选型时拧的三个旋钮&quot;">​</a></h3><ul><li><strong>分辨率</strong>：决定 LSB 与量化误差下限，也决定码值换算的比例</li><li><strong>采样率</strong>：由 t_samp + t_conv 决定，受信号带宽与源内阻约束</li><li><strong>参考源</strong>：决定量程与长期漂移，是精度的天花板</li></ul><p>三个旋钮互相牵制：要更快就得缩 t_samp，缩 t_samp 就要求源内阻更小；要更准就要更稳的参考和更多位数，更多位数又要求更长的采样时间把电容充到更小的误差内。理解这条牵制链，比记住任何一张寄存器表都耐用。</p><hr><p><em>本文档由 markdowncli 技能辅助生成</em></p>',57)])])}const q=t(n,[["render",s]]);export{m as __pageData,q as default};
